import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.CZo9GF0W.js";const m=JSON.parse('{"title":"08 — Testing & Quality Strategy","description":"","frontmatter":{},"headers":[],"relativePath":"08-TESTING.md","filePath":"08-TESTING.md","lastUpdated":1789060268000}'),n={name:"08-TESTING.md"};function i(s,e,d,c,l,h){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="_08-—-testing-quality-strategy" tabindex="-1">08 — Testing &amp; Quality Strategy <a class="header-anchor" href="#_08-—-testing-quality-strategy" aria-label="Permalink to &quot;08 — Testing &amp; Quality Strategy&quot;">​</a></h1><h2 id="layers" tabindex="-1">Layers <a class="header-anchor" href="#layers" aria-label="Permalink to &quot;Layers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Layer</th><th>Tool</th><th>Scope</th><th>Runs</th></tr></thead><tbody><tr><td>Unit</td><td>Vitest</td><td><code>core</code> pure logic: splitter, analyzer, <code>buildSelect</code>/<code>buildDml</code>, type handlers, cache, <code>SecretRef</code> resolution</td><td>every commit</td></tr><tr><td>Driver conformance</td><td>Vitest + docker (PG · SQLite · Mongo · Redis)</td><td>the shared kit from <code>03 §6</code>, per driver, per server version, through each driver&#39;s <code>EngineFixture</code></td><td>every commit</td></tr><tr><td>Integration</td><td>Vitest + docker: PG 13/15/17 · Redis 6.2/7 · Mongo 7 and an 8 replica set · MySQL 8 · MariaDB 11 · SQL Server 2022</td><td>connect, introspect, query, cancel, stream, transaction, edit-apply-rollback</td><td>every commit</td></tr><tr><td>Webview component</td><td>Vitest + Testing Library</td><td>grid virtualization, cell editors, filter row, staged edits</td><td>every commit</td></tr><tr><td>E2E</td><td><code>@vscode/test-electron</code></td><td>real VS Code: connect → browse → query → edit → export</td><td>PR + nightly</td></tr><tr><td>Performance</td><td>custom bench in CI</td><td>budgets below</td><td>PR (fail on regression)</td></tr><tr><td>Security</td><td>targeted suites</td><td>every <code>S*</code> requirement in <code>05-SECURITY.md</code></td><td>every commit</td></tr></tbody></table><h2 id="fixture-schema" tabindex="-1">Fixture schema <a class="header-anchor" href="#fixture-schema" aria-label="Permalink to &quot;Fixture schema&quot;">​</a></h2><p><code>test/fixtures/schema.sql</code> — deliberately nasty:</p><ul><li>Every PG type incl. arrays, nested composites, ranges, domains, enums, <code>bytea</code>, <code>interval</code>, <code>timestamptz</code>, <code>numeric(38,10)</code>, <code>int8</code> at max, <code>uuid</code>, <code>jsonb</code> with deep nesting, <code>vector(1536)</code> when pgvector is present.</li><li>Tables with: no PK · composite PK · generated columns · identity · partitions · inheritance · RLS policies · circular FKs · 200 columns · a name needing quoting (<code>&quot;weird Name&quot;</code>, unicode, embedded <code>&quot;</code>).</li><li>1M-row table for perf runs, generated by <code>generate_series</code>.</li><li>A view, a matview, a foreign table (postgres_fdw self-loop), functions in plpgsql + sql.</li></ul><h2 id="fixture-data-non-relational-mm" tabindex="-1">Fixture data, non-relational <strong>[MM]</strong> <a class="header-anchor" href="#fixture-data-non-relational-mm" aria-label="Permalink to &quot;Fixture data, non-relational **[MM]**&quot;">​</a></h2><p><code>test/fixtures/mongo-seed.js</code> — documents with disjoint key sets; every BSON type including Decimal128 at full precision and Int64 at max; deep nesting; arrays of subdocuments; a field that is a string in half the documents and a number in the other half; a field present in 1% of documents; keys containing dots, <code>$</code>, and unicode; a 16 MB document; a 100k-document collection for paging and a 1M-document one for the benchmark; a view; a collection with a <code>$jsonSchema</code> validator; a TTL index; a capped collection.</p><p><code>test/fixtures/redis-seed.txt</code> — a key of every type; a binary, non-UTF-8 value; a 5 MB value; a hash with 100 000 fields; a zset with float scores that must not lose precision; keys with separators at several depths, keys with none, keys with unicode and spaces; TTLs at second and millisecond precision; a stream with consumer groups and pending entries; 1M keys for the tree benchmark.</p><h2 id="correctness-invariants-non-relational-mm" tabindex="-1">Correctness invariants, non-relational <strong>[MM]</strong> <a class="header-anchor" href="#correctness-invariants-non-relational-mm" aria-label="Permalink to &quot;Correctness invariants, non-relational **[MM]**&quot;">​</a></h2><ol start="7"><li><strong>Projection stability:</strong> the sampled column union is deterministic for a given sample and does not reshuffle columns while paging.</li><li><strong>Missing survives:</strong> a field absent from a document round-trips as absent, never as null, and <code>$unset</code> is generated for removal rather than <code>$set: null</code>.</li><li><strong>Unknown fails closed:</strong> an unclassifiable command against a <code>prod</code> profile is refused without the typed confirmation.</li><li><strong>Partial-apply honesty:</strong> with <code>supportsAtomicEdits: false</code>, a batch whose third edit fails reports exactly the first two as applied.</li><li><strong>No <code>KEYS</code>, ever:</strong> the Redis suite asserts, against a 1M-key instance, that no code path issues <code>KEYS</code>, and that no tree request returns more than <code>pitta.explorer.treePageSize</code> keys.</li><li><strong>No evaluation:</strong> a <code>.mongodb.js</code> file containing <code>process.exit()</code>, <code>require(...)</code>, or a function call outside the allowlist produces a diagnostic and executes nothing.</li></ol><h2 id="performance-budgets-ci-enforced-from-phase-8" tabindex="-1">Performance budgets (CI-enforced from Phase 8) <a class="header-anchor" href="#performance-budgets-ci-enforced-from-phase-8" aria-label="Permalink to &quot;Performance budgets (CI-enforced from Phase 8)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Metric</th><th>Budget</th></tr></thead><tbody><tr><td>Extension activation</td><td>&lt; 200 ms</td></tr><tr><td>Tree expand, 10 000 objects</td><td>&lt; 1 s</td></tr><tr><td>First result page visible</td><td>&lt; 500 ms</td></tr><tr><td>Stream 1M × 20 cols</td><td>ext-host RSS &lt; 600 MB</td></tr><tr><td>Grid scroll</td><td>≥ 50 fps</td></tr><tr><td>Completion p95, 5 000 tables</td><td>&lt; 50 ms</td></tr><tr><td>Export 1M rows to CSV</td><td>RSS flat, no full materialization</td></tr></tbody></table><p>Every figure above is the target on a developer machine. A time budget measured where <code>CI</code> is set is scaled by <code>timeBudgetMs</code> in <code>test/bench/harness.ts</code>, because a shared runner is roughly half the speed and varies run to run: activation measures 174 ms locally and between 230 ms and 280 ms on GitHub&#39;s runners, which failed the build on commits that changed nothing about activation. The measured number is printed on every run whatever ceiling it was compared against, so a creeping regression stays visible - and a real one is a multiple, not a third.</p><h2 id="correctness-invariants-property-tests" tabindex="-1">Correctness invariants (property tests) <a class="header-anchor" href="#correctness-invariants-property-tests" aria-label="Permalink to &quot;Correctness invariants (property tests)&quot;">​</a></h2><ol><li><strong>Round-trip:</strong> for every type, <code>write(v)</code> → <code>read()</code> → equal. <code>numeric</code> compared as string.</li><li><strong>No lossy numbers:</strong> no code path passes <code>numeric</code>/<code>int8</code> through <code>Number</code>. Enforced by an eslint rule <em>and</em> a runtime assertion in dev builds.</li><li><strong>Params only:</strong> every generated statement&#39;s user-supplied values appear in the params array, never the SQL text. Property test over random filter/edit sets.</li><li><strong>Transaction atomicity:</strong> an edit batch with a deliberately failing final statement leaves the DB byte-identical to before.</li><li><strong>Cancel really cancels:</strong> after <code>cancel()</code>, the backend PID has no active query within 1 s.</li><li><strong>Identifier safety:</strong> objects named with quotes, dots, unicode, and reserved words are browsable, queryable, and editable.</li></ol><h2 id="manual-qa-checklist-per-release" tabindex="-1">Manual QA checklist (per release) <a class="header-anchor" href="#manual-qa-checklist-per-release" aria-label="Permalink to &quot;Manual QA checklist (per release)&quot;">​</a></h2><p>macOS / Linux / Windows × local · Remote-SSH · WSL · devcontainer · Codespaces (expect: works, with the remote-localhost caveat) · Cursor + VSCodium via Open VSX · light/dark/high-contrast themes · screen-reader pass on the grid.</p>',18)])])}const p=t(n,[["render",i]]);export{m as __pageData,p as default};
